from fastapi import APIRouter, Query

from src.modules.tasks.presenter.dtos import CreateTaskRequestDto, ListTasksResponseDto, TaskResponseDto
from src.modules.tasks.usecases import CreateTaskUsecaseDep, ListTasksUsecaseDep

task_router = APIRouter(tags=["tasks"])

ERROR = {"description": "Error envelope: {error: {code, message, details}}"}


@task_router.post(
    "/tasks",
    operation_id="task.create",
    response_model=TaskResponseDto,
    status_code=201,
    responses={422: ERROR},
)
async def create_task(body: CreateTaskRequestDto, usecase: CreateTaskUsecaseDep) -> TaskResponseDto:
    return await usecase.execute(body)


@task_router.get("/tasks", operation_id="task.list", response_model=ListTasksResponseDto)
async def list_tasks(
    usecase: ListTasksUsecaseDep,
    limit: int = Query(default=20, ge=1, le=100),
    offset: int = Query(default=0, ge=0),
) -> ListTasksResponseDto:
    return await usecase.execute(None, limit, offset)

